leaf_costs = dict(cells('Leaf costs', 'E30:F32'))

def expand(part, mult):
    if part in leaf_costs:
        return {part: mult}
    res = {}
    for p, c, u in rules:
        if p == part:
            sub = expand(c, u * mult)
            for k, v in sub.items():
                res[k] = res.get(k, 0) + v
    return res

quantities = expand('Beacon', 1)
result = [quantities.get('Alloy', 0), quantities.get('Bolt', 0), quantities.get('Wire', 0)]

